-- =============================================================================
-- LipaKit: complete database setup in one file.
-- Paste into Supabase → SQL Editor → Run, on a NEW project. Generated by
-- `pnpm db:bundle` from supabase/migrations/*.sql and supabase/seed.sql; don't edit by hand.
-- (With the Supabase CLI, use `supabase db push` instead, which runs the same files.)
-- =============================================================================

-- >>> supabase/migrations/20261121000001_schema.sql
-- =============================================================================
-- LipaKit schema: tables, constraints, indexes, triggers.
-- RLS policies live in the next migration so each file stays readable.
--
-- Conventions
--   * Every table: id uuid PK, created_at timestamptz.
--   * Money is integer Kenyan shillings (M-Pesa has no cents).
--   * Status columns are text + CHECK rather than Postgres enums, because
--     adding a value to a CHECK is a one-line migration and enums are not.
-- =============================================================================

create extension if not exists pgcrypto with schema extensions;

-- -----------------------------------------------------------------------------
-- Helper: keep updated_at current on mutable tables.
-- -----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- profiles: one row per auth user. Created automatically on sign-up.
-- -----------------------------------------------------------------------------
create table public.profiles (
  id               uuid primary key references auth.users (id) on delete cascade,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  full_name        text,
  email            text,
  phone            text check (phone is null or phone ~ '^254[17][0-9]{8}$'),
  role             text not null default 'user' check (role in ('user', 'admin')),
  telegram_chat_id bigint unique
);

comment on column public.profiles.phone is 'Normalised Kenyan MSISDN, e.g. 254712345678.';
comment on column public.profiles.email is 'Copied from auth.users on sign-up for admin search. auth.users stays the source of truth.';

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- Create a profile whenever a user signs up (magic link, Google, ...).
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, email, full_name)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name')
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- -----------------------------------------------------------------------------
-- plans: what you sell. Displayed on the pricing page.
-- -----------------------------------------------------------------------------
create table public.plans (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  code        text not null unique check (code ~ '^[a-z0-9_]+$'),
  name        text not null,
  description text,
  price_kes   integer not null check (price_kes > 0),
  interval    text not null check (interval in ('month', 'quarter', 'year')),
  trial_days  integer not null default 0 check (trial_days >= 0),
  -- Feature keys this plan unlocks, e.g. {"reports": true, "max_projects": 5}.
  features    jsonb not null default '{}'::jsonb check (jsonb_typeof(features) = 'object'),
  sort_order  integer not null default 0,
  is_active   boolean not null default true
);

create trigger plans_set_updated_at
  before update on public.plans
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- subscriptions: a user's access to a plan over time.
-- There is no auto-debit with M-Pesa; renewals are paid orders (see docs/04-billing.md).
-- -----------------------------------------------------------------------------
create table public.subscriptions (
  id                   uuid primary key default gen_random_uuid(),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  user_id              uuid not null references public.profiles (id) on delete cascade,
  plan_id              uuid not null references public.plans (id),
  status               text not null check (status in ('trialing', 'active', 'grace', 'expired', 'canceled')),
  current_period_start timestamptz not null,
  current_period_end   timestamptz not null,
  grace_until          timestamptz,
  cancel_at_period_end boolean not null default false,
  check (current_period_end > current_period_start)
);

-- One live subscription per user keeps billing logic simple in v1.
create unique index subscriptions_one_live_per_user
  on public.subscriptions (user_id)
  where status in ('trialing', 'active', 'grace');

create index subscriptions_period_end_idx on public.subscriptions (current_period_end)
  where status in ('trialing', 'active', 'grace');

create trigger subscriptions_set_updated_at
  before update on public.subscriptions
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- orders: something a user owes money for. Created BEFORE calling Daraja.
-- -----------------------------------------------------------------------------
create table public.orders (
  id              uuid primary key default gen_random_uuid(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  user_id         uuid not null references public.profiles (id) on delete cascade,
  subscription_id uuid references public.subscriptions (id) on delete set null,
  plan_id         uuid references public.plans (id),
  purpose         text not null check (purpose in ('subscription', 'renewal', 'one_off')),
  amount_kes      integer not null check (amount_kes > 0),
  -- Shown to the customer and used as the Paybill account number for C2B.
  -- Daraja limits AccountReference to 12 characters (confirm with Safaricom).
  account_ref     text not null unique check (char_length(account_ref) between 4 and 12),
  status          text not null default 'pending'
                  check (status in ('pending', 'paid', 'failed', 'expired', 'needs_review', 'cancelled')),
  status_reason   text,
  paid_at         timestamptz,
  check ((status = 'paid') = (paid_at is not null) or status = 'needs_review')
);

create index orders_user_id_idx on public.orders (user_id, created_at desc);
create index orders_status_idx on public.orders (status) where status in ('pending', 'needs_review');

create trigger orders_set_updated_at
  before update on public.orders
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- mpesa_transactions: one row per Daraja money movement (STK, C2B, B2C).
-- The unique constraints are the idempotency backbone: a repeated callback
-- cannot create a second transaction.
-- -----------------------------------------------------------------------------
create table public.mpesa_transactions (
  id                  uuid primary key default gen_random_uuid(),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  order_id            uuid references public.orders (id) on delete set null,
  kind                text not null check (kind in ('stk', 'c2b', 'b2c')),
  merchant_request_id text,
  checkout_request_id text unique,
  mpesa_receipt       text unique,
  phone               text,
  amount_kes          integer check (amount_kes is null or amount_kes > 0),
  result_code         integer,
  result_desc         text,
  status              text not null default 'pending'
                      check (status in ('pending', 'success', 'failed', 'cancelled', 'timeout', 'unmatched')),
  -- Last raw Daraja payload for this transaction, for debugging.
  raw                 jsonb,
  check (kind <> 'stk' or checkout_request_id is not null)
);

create index mpesa_transactions_order_id_idx on public.mpesa_transactions (order_id);
create index mpesa_transactions_pending_idx on public.mpesa_transactions (created_at)
  where status = 'pending';
create index mpesa_transactions_unmatched_idx on public.mpesa_transactions (created_at)
  where status = 'unmatched';

create trigger mpesa_transactions_set_updated_at
  before update on public.mpesa_transactions
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- mpesa_callbacks: raw log of every inbound Daraja callback, written FIRST.
-- Nothing is ever lost: processing errors are recorded on the row.
-- -----------------------------------------------------------------------------
create table public.mpesa_callbacks (
  id           uuid primary key default gen_random_uuid(),
  created_at   timestamptz not null default now(),
  kind         text not null check (kind in ('stk', 'c2b_validate', 'c2b_confirm', 'b2c_result', 'b2c_timeout')),
  payload      jsonb not null,
  received_at  timestamptz not null default now(),
  processed_at timestamptz,
  error        text,
  replay_count integer not null default 0
);

create index mpesa_callbacks_received_at_idx on public.mpesa_callbacks (received_at desc);
create index mpesa_callbacks_unprocessed_idx on public.mpesa_callbacks (received_at)
  where processed_at is null;

-- -----------------------------------------------------------------------------
-- receipts: one per paid order. PDF lives in Supabase Storage.
-- -----------------------------------------------------------------------------
create table public.receipts (
  id         uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  order_id   uuid not null unique references public.orders (id) on delete restrict,
  number     text not null unique,
  pdf_path   text,
  emailed_at timestamptz,
  sms_at     timestamptz
);

-- >>> supabase/migrations/20261121000002_rls.sql
-- =============================================================================
-- Row Level Security.
--
-- Rules (from the brief):
--   * Users read only their own rows.
--   * Admins (profiles.role = 'admin') read everything.
--   * Payment tables are written only server-side with the service role,
--     which bypasses RLS. So there are deliberately NO insert/update/delete
--     policies on plans, subscriptions, orders, mpesa_*, or receipts.
-- =============================================================================

-- is_admin(): security definer so it can read profiles without recursing
-- through the profiles RLS policy that calls it.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles
    where id = (select auth.uid()) and role = 'admin'
  );
$$;

revoke all on function public.is_admin() from public;
-- anon needs execute too: the public plans policy calls it (it just returns false).
grant execute on function public.is_admin() to anon, authenticated, service_role;

alter table public.profiles           enable row level security;
alter table public.plans              enable row level security;
alter table public.subscriptions      enable row level security;
alter table public.orders             enable row level security;
alter table public.mpesa_transactions enable row level security;
alter table public.mpesa_callbacks    enable row level security;
alter table public.receipts           enable row level security;

-- --- profiles ----------------------------------------------------------------
create policy "profiles: read own or admin"
  on public.profiles for select to authenticated
  using (id = (select auth.uid()) or (select public.is_admin()));

create policy "profiles: update own"
  on public.profiles for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- Column-level guard: users may edit their name and phone, never their role
-- or Telegram link (those are set server-side).
revoke update on public.profiles from authenticated, anon;
grant update (full_name, phone) on public.profiles to authenticated;

-- --- plans: public catalogue ---------------------------------------------------
create policy "plans: anyone reads active plans"
  on public.plans for select to anon, authenticated
  using (is_active or (select public.is_admin()));

-- --- user-owned payment tables --------------------------------------------------
create policy "subscriptions: read own or admin"
  on public.subscriptions for select to authenticated
  using (user_id = (select auth.uid()) or (select public.is_admin()));

create policy "orders: read own or admin"
  on public.orders for select to authenticated
  using (user_id = (select auth.uid()) or (select public.is_admin()));

create policy "mpesa_transactions: read own or admin"
  on public.mpesa_transactions for select to authenticated
  using (
    (select public.is_admin())
    or exists (
      select 1 from public.orders o
      where o.id = mpesa_transactions.order_id and o.user_id = (select auth.uid())
    )
  );

create policy "receipts: read own or admin"
  on public.receipts for select to authenticated
  using (
    (select public.is_admin())
    or exists (
      select 1 from public.orders o
      where o.id = receipts.order_id and o.user_id = (select auth.uid())
    )
  );

-- --- callback log: admins only (raw payloads include phone numbers) -------------
create policy "mpesa_callbacks: admin reads"
  on public.mpesa_callbacks for select to authenticated
  using ((select public.is_admin()));

-- >>> supabase/migrations/20261121000003_mpesa_settlement.sql
-- =============================================================================
-- M-Pesa settlement: the atomic, idempotent "this STK push is now final" step.
--
-- The decision (which status, which message) is made in TypeScript
-- (src/lib/reconcile/stk.ts, unit tested). This function only applies it, and
-- guarantees that a transaction leaves `pending` exactly once, even when the
-- callback, a duplicate callback and the poller arrive at the same moment.
-- =============================================================================

create or replace function public.mpesa_settle_stk(
  p_checkout_request_id text,
  p_tx_status           text,
  p_order_status        text,
  p_order_reason        text,
  -- Optional parameters default to null, so generated TypeScript types mark them optional.
  p_result_code         integer default null,
  p_result_desc         text    default null,
  p_receipt             text    default null,
  p_phone               text    default null,
  p_raw                 jsonb   default null
)
returns text   -- 'settled' | 'noop' | 'receipt_added'
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_tx public.mpesa_transactions%rowtype;
begin
  -- Row lock: concurrent callers queue here, and the second one sees the first one's result.
  select * into v_tx
  from public.mpesa_transactions
  where checkout_request_id = p_checkout_request_id and kind = 'stk'
  for update;

  if not found then
    raise exception 'unknown checkout_request_id %', p_checkout_request_id using errcode = 'no_data_found';
  end if;

  if v_tx.status <> 'pending' then
    -- Already final. The only thing a later message may add is a missing receipt
    -- (the poller can settle a success before the callback brings the receipt).
    if v_tx.status = 'success' and v_tx.mpesa_receipt is null and p_receipt is not null then
      update public.mpesa_transactions set mpesa_receipt = p_receipt where id = v_tx.id;
      return 'receipt_added';
    end if;
    return 'noop';
  end if;

  update public.mpesa_transactions
  set status        = p_tx_status,
      result_code   = p_result_code,
      result_desc   = p_result_desc,
      mpesa_receipt = coalesce(p_receipt, mpesa_receipt),
      phone         = coalesce(p_phone, phone),
      raw           = coalesce(p_raw, raw)
  where id = v_tx.id;

  -- The order only moves if nothing else has finalised it yet.
  -- (M3 extends this step: activate/extend the subscription and create the receipt.)
  update public.orders
  set status        = p_order_status,
      status_reason = p_order_reason,
      paid_at       = case when p_order_status in ('paid', 'needs_review') then now() else paid_at end
  where id = v_tx.order_id and status = 'pending';

  return 'settled';
end;
$$;

-- Server-side only. Without this, any signed-in user could call it through the
-- API and mark their own order paid.
revoke all on function public.mpesa_settle_stk(text, text, text, text, integer, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.mpesa_settle_stk(text, text, text, text, integer, text, text, text, jsonb) to service_role;

-- <MpesaCheckout /> listens for its order's status over Supabase Realtime.
-- Realtime respects RLS, so users only receive changes to their own orders.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.orders;
  end if;
end;
$$;

-- >>> supabase/migrations/20261121000004_scheduled_jobs.sql
-- =============================================================================
-- Scheduled jobs that run in YOUR Supabase project (pg_cron + pg_net), on any
-- Supabase plan. They call the app's protected /api/cron/* routes.
--
-- Why not Vercel Cron: on Vercel's Hobby plan, a cron that runs more than once
-- a day fails the deployment. pg_cron runs every minute on every Supabase plan.
--
-- This migration only creates helper functions; nothing is scheduled until you
-- run, once, in the Supabase SQL editor (see docs/05-deploy.md):
--
--   select public.lipakit_schedule_jobs('https://your-app.vercel.app', 'your-CRON_SECRET');
--
-- Re-run it after changing your domain or CRON_SECRET. To stop everything:
--
--   select public.lipakit_unschedule_jobs();
-- =============================================================================

create or replace function public.lipakit_schedule_jobs(p_app_url text, p_cron_secret text)
returns setof text  -- names of the jobs now scheduled
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_url text := rtrim(p_app_url, '/');
begin
  if v_url !~ '^https://' then
    raise exception 'p_app_url must be your public https:// URL, e.g. https://your-app.vercel.app';
  end if;
  if char_length(p_cron_secret) < 16 then
    raise exception 'p_cron_secret must be the CRON_SECRET from your app environment (16+ characters)';
  end if;

  -- Both extensions are available on every Supabase plan.
  create extension if not exists pg_cron with schema pg_catalog;
  create extension if not exists pg_net with schema extensions;

  -- Secrets live in Supabase Vault, encrypted at rest, never in the job text.
  -- Note: while a request is queued, pg_net stores its headers in
  -- net.http_request_queue, readable by database roles that can log in. CRON_SECRET
  -- only allows triggering the cron routes, so the exposure is limited.
  delete from vault.secrets where name in ('lipakit_app_url', 'lipakit_cron_secret');
  perform vault.create_secret(v_url, 'lipakit_app_url');
  perform vault.create_secret(p_cron_secret, 'lipakit_cron_secret');

  -- M-Pesa status poller: every minute.
  perform cron.schedule(
    'lipakit-mpesa-poll',
    '* * * * *',
    $job$
      select net.http_get(
        url := (select decrypted_secret from vault.decrypted_secrets where name = 'lipakit_app_url') || '/api/cron/mpesa-poll',
        headers := jsonb_build_object(
          'Authorization', 'Bearer ' || (select decrypted_secret from vault.decrypted_secrets where name = 'lipakit_cron_secret')
        ),
        timeout_milliseconds := 55000
      );
    $job$
  );
  return next 'lipakit-mpesa-poll';

  -- A later migration (billing) adds the daily renewals job here.
end;
$$;

create or replace function public.lipakit_unschedule_jobs()
returns setof text  -- names of the jobs removed
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_job record;
begin
  for v_job in select jobname from cron.job where jobname like 'lipakit-%' loop
    perform cron.unschedule(v_job.jobname);
    return next v_job.jobname;
  end loop;
  delete from vault.secrets where name in ('lipakit_app_url', 'lipakit_cron_secret');
end;
$$;

-- Only the database owner (you, in the SQL editor) may schedule jobs. Never the API.
revoke all on function public.lipakit_schedule_jobs(text, text) from public, anon, authenticated;
revoke all on function public.lipakit_unschedule_jobs() from public, anon, authenticated;

-- >>> supabase/migrations/20261121000005_billing.sql
-- =============================================================================
-- Billing: subscriptions follow paid orders, receipts, C2B settlement, Ratiba.
--
-- One rule holds everywhere: "order becomes paid" → "receipt exists" and
-- "subscription is activated or extended" happen in the SAME transaction,
-- inside billing_apply_paid_order(). Every settle path (STK, C2B, Ratiba)
-- calls it, so there is exactly one place that grants access for money.
-- =============================================================================

-- --- Subscriptions: renewal method and Ratiba standing order ------------------
alter table public.subscriptions
  add column renewal_method text not null default 'manual' check (renewal_method in ('manual', 'ratiba')),
  -- AccountReference on the customer's standing order; how Ratiba payments find this subscription.
  add column ratiba_account_ref text unique
    check (ratiba_account_ref is null or char_length(ratiba_account_ref) between 4 and 12),
  add column ratiba_status text
    check (ratiba_status is null or ratiba_status in ('requested', 'active', 'failed', 'cancelled'));

-- --- Transactions and callbacks: new kinds and C2B fields ---------------------
alter table public.mpesa_transactions drop constraint mpesa_transactions_kind_check;
alter table public.mpesa_transactions
  add constraint mpesa_transactions_kind_check check (kind in ('stk', 'c2b', 'b2c', 'ratiba')),
  -- C2B: the account number the customer typed (BillRefNumber), kept for the unmatched queue.
  add column account_ref text,
  -- C2B: when M-Pesa says the payment happened (TransTime).
  add column transaction_time timestamptz;

create index mpesa_transactions_c2b_ref_idx on public.mpesa_transactions (account_ref) where kind = 'c2b';

alter table public.mpesa_callbacks drop constraint mpesa_callbacks_kind_check;
alter table public.mpesa_callbacks
  add constraint mpesa_callbacks_kind_check
  check (kind in ('stk', 'c2b_validate', 'c2b_confirm', 'b2c_result', 'b2c_timeout', 'ratiba'));

-- --- Receipt numbers: PREFIX-YEAR-000123, gap-free per paid order --------------
create sequence public.receipt_number_seq;
revoke all on sequence public.receipt_number_seq from public, anon, authenticated;

create or replace function public.next_receipt_number(p_prefix text)
returns text
language sql
volatile
set search_path = ''
as $$
  select p_prefix || '-' || to_char(now() at time zone 'Africa/Nairobi', 'YYYY') || '-'
         || lpad(nextval('public.receipt_number_seq')::text, 6, '0');
$$;

-- --- The one place money turns into access ------------------------------------
create or replace function public.billing_apply_paid_order(p_order_id uuid, p_receipt_prefix text default 'LK')
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_sub   public.subscriptions%rowtype;
  v_plan  public.plans%rowtype;
  v_step  interval;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found or v_order.status <> 'paid' then
    return;
  end if;

  -- Receipt: one per paid order. Checked first so a re-run never burns a number.
  if not exists (select 1 from public.receipts where order_id = v_order.id) then
    insert into public.receipts (order_id, number)
    values (v_order.id, public.next_receipt_number(p_receipt_prefix));
  end if;

  if v_order.purpose not in ('subscription', 'renewal') then
    return;
  end if;

  -- Which subscription? The one on the order if it's still live, else the user's live one.
  if v_order.subscription_id is not null then
    select * into v_sub from public.subscriptions where id = v_order.subscription_id for update;
  end if;
  if v_sub.id is null or v_sub.status not in ('trialing', 'active', 'grace') then
    select * into v_sub from public.subscriptions
    where user_id = v_order.user_id and status in ('trialing', 'active', 'grace')
    for update;
  end if;

  select * into v_plan from public.plans where id = coalesce(v_order.plan_id, v_sub.plan_id);
  if v_plan.id is null then
    raise exception 'order % is a % order but has no plan', v_order.id, v_order.purpose;
  end if;
  v_step := case v_plan.interval
              when 'month'   then interval '1 month'
              when 'quarter' then interval '3 months'
              else                interval '1 year'
            end;

  if v_sub.id is not null then
    -- Extend from the OLD period end, not the payment date: paying early never
    -- loses days, and paying during grace doesn't gift the grace days.
    -- A plan change on the order takes effect here (see docs/04-billing.md).
    update public.subscriptions
    set status               = 'active',
        plan_id              = v_plan.id,
        current_period_start = v_sub.current_period_end,
        current_period_end   = v_sub.current_period_end + v_step,
        grace_until          = null,
        cancel_at_period_end = false
    where id = v_sub.id;
  else
    insert into public.subscriptions (user_id, plan_id, status, current_period_start, current_period_end)
    values (v_order.user_id, v_plan.id, 'active', now(), now() + v_step)
    returning * into v_sub;
  end if;

  update public.orders set subscription_id = v_sub.id
  where id = v_order.id and subscription_id is distinct from v_sub.id;

  -- Other unpaid renewal bills for this subscription are now moot. Leave any
  -- with an STK push still in flight; they settle (and extend) on their own.
  update public.orders o
  set status = 'cancelled', status_reason = 'Superseded: renewed by payment ' || v_order.account_ref
  where o.subscription_id = v_sub.id
    and o.purpose = 'renewal'
    and o.status = 'pending'
    and o.id <> v_order.id
    and not exists (
      select 1 from public.mpesa_transactions t where t.order_id = o.id and t.status = 'pending'
    );
end;
$$;

-- --- STK settlement, v2: also applies billing, and tolerates C2B getting there first
-- (A Paybill with C2B URLs registered also sends a C2B confirmation for STK payments,
-- with TransID equal to the STK receipt. Whichever arrives first settles the order.)
drop function public.mpesa_settle_stk(text, text, text, text, integer, text, text, text, jsonb);

create or replace function public.mpesa_settle_stk(
  p_checkout_request_id text,
  p_tx_status           text,
  p_order_status        text,
  p_order_reason        text,
  p_result_code         integer default null,
  p_result_desc         text    default null,
  p_receipt             text    default null,
  p_phone               text    default null,
  p_raw                 jsonb   default null,
  p_receipt_prefix      text    default 'LK'
)
returns text   -- 'settled' | 'noop' | 'receipt_added'
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_tx      public.mpesa_transactions%rowtype;
  v_receipt text;
  v_rows    integer;
begin
  select * into v_tx
  from public.mpesa_transactions
  where checkout_request_id = p_checkout_request_id and kind = 'stk'
  for update;

  if not found then
    raise exception 'unknown checkout_request_id %', p_checkout_request_id using errcode = 'no_data_found';
  end if;

  -- Don't store a receipt number some other row (a C2B confirmation) already holds.
  v_receipt := case
                 when p_receipt is null then null
                 when exists (select 1 from public.mpesa_transactions
                              where mpesa_receipt = p_receipt and id <> v_tx.id) then null
                 else p_receipt
               end;

  if v_tx.status <> 'pending' then
    if v_tx.status = 'success' and v_tx.mpesa_receipt is null and v_receipt is not null then
      update public.mpesa_transactions set mpesa_receipt = v_receipt where id = v_tx.id;
      return 'receipt_added';
    end if;
    return 'noop';
  end if;

  update public.mpesa_transactions
  set status        = p_tx_status,
      result_code   = p_result_code,
      result_desc   = p_result_desc,
      mpesa_receipt = coalesce(v_receipt, mpesa_receipt),
      phone         = coalesce(p_phone, phone),
      raw           = coalesce(p_raw, raw)
  where id = v_tx.id;

  update public.orders
  set status        = p_order_status,
      status_reason = p_order_reason,
      paid_at       = case when p_order_status in ('paid', 'needs_review') then now() else paid_at end
  where id = v_tx.order_id and status = 'pending';
  get diagnostics v_rows = row_count;

  if v_rows > 0 and p_order_status = 'paid' then
    perform public.billing_apply_paid_order(v_tx.order_id, p_receipt_prefix);
  end if;

  return 'settled';
end;
$$;

-- --- C2B settlement (Paybill/Till payments, including Ratiba executions) -------
-- The matching decision (which order, paid or needs_review) is made in
-- TypeScript (src/lib/reconcile/c2b.ts). This applies it atomically. TransID
-- is unique, so a repeated confirmation is a no-op.
create or replace function public.mpesa_settle_c2b(
  p_trans_id        text,
  p_amount          integer,
  p_account_ref     text,
  p_phone           text,
  p_trans_time      timestamptz,
  p_raw             jsonb,
  p_order_id        uuid default null,   -- matched order, if any
  p_subscription_id uuid default null,   -- matched Ratiba subscription, if any (an order is created)
  p_order_status    text default null,   -- 'paid' | 'needs_review' when matched
  p_order_reason    text default null,
  p_receipt_prefix  text default 'LK'
)
returns text   -- 'settled' | 'needs_review' | 'unmatched' | 'duplicate' | 'noop'
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_order_id uuid := p_order_id;
  v_created  boolean := false;
  v_sub      public.subscriptions%rowtype;
  v_plan     public.plans%rowtype;
  v_tx_id    uuid;
  v_rows     integer;
begin
  if exists (select 1 from public.mpesa_transactions where mpesa_receipt = p_trans_id) then
    return 'noop';
  end if;

  -- A Ratiba execution: create the renewal order it pays for.
  if v_order_id is null and p_subscription_id is not null then
    select * into v_sub from public.subscriptions where id = p_subscription_id;
    select * into v_plan from public.plans where id = v_sub.plan_id;
    if v_sub.id is not null then
      insert into public.orders (user_id, subscription_id, plan_id, purpose, amount_kes, account_ref)
      values (
        v_sub.user_id, v_sub.id, v_sub.plan_id, 'renewal', coalesce(v_plan.price_kes, p_amount),
        left(p_receipt_prefix || 'R' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 9)), 12)
      )
      returning id into v_order_id;
      v_created := true;
    end if;
  end if;

  insert into public.mpesa_transactions
    (order_id, kind, mpesa_receipt, phone, amount_kes, status, account_ref, transaction_time, raw, result_code, result_desc)
  values
    (v_order_id, 'c2b', p_trans_id, p_phone, p_amount,
     case when v_order_id is null then 'unmatched' else 'success' end,
     p_account_ref, p_trans_time, p_raw, 0, 'C2B confirmation')
  on conflict (mpesa_receipt) do nothing
  returning id into v_tx_id;

  if v_tx_id is null then
    -- Lost a race with an identical confirmation.
    if v_created then delete from public.orders where id = v_order_id; end if;
    return 'noop';
  end if;

  if v_order_id is null then
    return 'unmatched';
  end if;

  -- A late Paybill payment may pay an order whose STK attempt expired or failed.
  update public.orders
  set status = p_order_status, status_reason = p_order_reason, paid_at = now()
  where id = v_order_id and status in ('pending', 'expired', 'failed', 'cancelled');
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    -- Already paid: this is money on top. Put it in the unmatched queue for a human.
    update public.mpesa_transactions
    set status = 'unmatched', result_desc = 'Order was already paid: possible double payment'
    where id = v_tx_id;
    return 'duplicate';
  end if;

  if p_order_status = 'paid' then
    perform public.billing_apply_paid_order(v_order_id, p_receipt_prefix);
    return 'settled';
  end if;
  return 'needs_review';
end;
$$;

-- Server-side only, like every money-moving function.
revoke all on function public.next_receipt_number(text) from public, anon, authenticated;
revoke all on function public.billing_apply_paid_order(uuid, text) from public, anon, authenticated;
revoke all on function public.mpesa_settle_stk(text, text, text, text, integer, text, text, text, jsonb, text)
  from public, anon, authenticated;
revoke all on function public.mpesa_settle_c2b(text, integer, text, text, timestamptz, jsonb, uuid, uuid, text, text, text)
  from public, anon, authenticated;
grant execute on function public.next_receipt_number(text) to service_role;
grant execute on function public.billing_apply_paid_order(uuid, text) to service_role;
grant execute on function public.mpesa_settle_stk(text, text, text, text, integer, text, text, text, jsonb, text) to service_role;
grant execute on function public.mpesa_settle_c2b(text, integer, text, text, timestamptz, jsonb, uuid, uuid, text, text, text)
  to service_role;

-- --- Receipt PDFs: private bucket, served only through signed URLs -------------
